'use strict';
function X(){return W().extra||(W().extra={importState:'idle',created:[],archived:false,offline:'conflict',consents:[]})}
function peopleLifecyclePage(){const x=X();return sHead('sPeopleLifecycle','S16–S19/S66 · J06/J07/J08')+sPolicy('D-003/D-004/D-015',q('No real file parsing, child data, account or guardian link. Import fixtures create domain records only.','لا تحليل ملفات فعلية أو بيانات طفل أو حساب أو علاقة ولي أمر. أمثلة الاستيراد تنشئ سجلات مجال فقط.'))+`<div class="form-panel">${errorBox()}<div class="work-card"><h2>${q('Controlled import','استيراد مضبوط')}</h2>${property(q('Input manifest','قائمة الإدخال'),'synthetic-import-v1 · 4 rows')}${property(q('Preview reconciliation','تسوية المعاينة'),q('2 eligible · 1 duplicate review · 1 invalid branch','٢ مؤهلان · ١ لمراجعة التشابه · ١ بفرع غير صالح'))}${property(q('Committed / skipped','المحفوظ والمتروك'),`${x.created.length} / ${x.importState==='complete'?2:0}`)}${property(t('status'),q(x.importState,({idle:'لم يبدأ','preview ready':'المعاينة جاهزة',complete:'مكتمل'})[x.importState]))}${sConfirm('import-review')}${sButtons(btn(q('Validate synthetic manifest','التحقق من القائمة الاصطناعية'),'s-import-preview'),btn(q('Commit eligible rows only · partial batch','حفظ المؤهل فقط · دفعة جزئية'),'s-import-commit','primary'),btn(q('Reconcile original import intent','تسوية نية الاستيراد الأصلية'),'s-import-reconcile'))}</div><div class="section work-card"><h3>${q('Archive / restore','الأرشفة والاستعادة')}</h3>${property(q('Player fixture','نموذج اللاعب'),'DEMO-ARCHIVE-1')}${property(t('status'),x.archived?q('Archived · history preserved','مؤرشف · التاريخ محفوظ'):q('Active fixture','مثال نشط'))}${sField('archive-reason','Lifecycle reason','سبب تغيير الحالة')}${sConfirm('archive-review')}${sButtons(btn(q('Archive future eligibility fixture','أرشفة الأهلية المستقبلية تجريبياً'),'s-player-archive'),btn(q('Restore after review','استعادة بعد المراجعة'),'s-player-restore'))}</div>${notice(q('Relationship, payer and consent remain separate','العلاقة والدفع والموافقة منفصلة'),q('Import does not verify identity, invite guardians or grant payer/consent access. Use the connected Batch2 relationship journey.','الاستيراد لا يتحقق من الهوية أو يدعو أولياء الأمور أو يمنح سلطة دفع أو موافقة. استخدم رحلة العلاقة المتصلة بالدفعة الثانية.'))}</div>`}
function offlinePage(){const state=X().offline;return sHead('sOffline','S30 · J14 · Later policy-gated concept')+sPolicy('D-011',q('Offline capture is unavailable. The queue below is a design fixture, not records saved on a device or a sync implementation.','الحضور دون اتصال غير متاح. القائمة التالية مثال تصميم وليست سجلات محفوظة على الجهاز أو تنفيذاً للمزامنة.'))+`<div class="form-panel"><div class="work-card">${property(q('Queue scope','نطاق القائمة'),'Demo identity · LAB-OFFLINE · one dated session')}${property(q('Lease / max age / retention','التفويض والمدة والاحتفاظ'),q('Policy to confirm · no duration selected','سياسة للتأكيد · لم تُختَر مدة'))}${property(q('Item A','العنصر أ'),q('Acknowledged by matching operation/payload fixture','إقرار مطابق للعملية والحمولة تجريبياً'))}${property(q('Item B','العنصر ب'),state==='conflict'?q('Conflict: local Present / current Absent','تعارض: محلي حاضر / حالي غائب'):q('Conflict referred to review · original intent retained','التعارض محال للمراجعة · النية الأصلية محفوظة'))}${property(q('Item C','العنصر ج'),q('Denied after assignment revocation · never replay under another identity','مرفوض بعد إلغاء التكليف · لا يُعاد بهوية أخرى'))}${sButtons(btn(q('Keep intent and refer conflict','حفظ النية وإحالة التعارض'),'s-offline-review'),btn(q('Inspect mixed acknowledgment fixture','فحص مثال الإقرار المختلط'),'s-offline-mixed'))}</div>${notice(q('Physical recovery remains unverified','التعافي الفعلي غير متحقق منه'),q('Device closure, eviction, storage quota, schema upgrades and airplane-mode replay require a separately accepted offline design and real-device proof.','إغلاق الجهاز والإخلاء والسعة وترقيات المخطط وإعادة الإرسال بوضع الطيران تتطلب تصميماً معتمداً ودليل جهاز فعلي.'))}</div>`}
function releasePage(){return sHead('sRelease','S68 · Release inventory / N1 concepts')+`<div class="form-panel"><div class="work-card">${[['F0','Identity / tenancy / design foundation','أساس الهوية والعزل والتصميم'],['P1','People / sessions / online attendance pilot','تجربة الأشخاص والحصص والحضور المتصل'],['R1','Agreed complete operating / financial web journeys','رحلات الويب التشغيلية والمالية المتفق عليها'],['R2','Advanced channels / public media if approved','قنوات متقدمة ووسائط عامة إن اعتُمدت'],['N1','Native iOS / Android concepts after stable web APIs','مفاهيم أصلية بعد استقرار واجهات الويب']].map(([id,en,ar])=>property(id,q(en,ar))).join('')}</div>${notice(q('Native concept directions retained','اتجاهات التطبيقات الأصلية محفوظة'),q('Trainer: assigned session and policy-gated offline queue. Guardian: authorized child, next action, published progress and permitted payer tasks. Player: policy-eligible own schedule/goals. These are later concepts, not native builds.','المدرب: الحصة المكلّف بها وقائمة غير متصلة مشروطة بالسياسة. الولي: الطفل المصرح والخطوة التالية والتقدم المنشور ومهام الدافع المصرح. اللاعب: جدوله وأهدافه إن سمحت السياسة. هذه مفاهيم لاحقة وليست تطبيقات أصلية.'))}${sPolicy('D-018/D-020',q('Release placement remains proposed. Local prototype availability does not enable a product capability.','موضع الإصدار مقترح. إتاحة النموذج المحلي لا تفعّل وظيفة بالمنتج.'))}</div>`}
function expandedAction(k){const x=X();if(k==='s-import-preview'){x.importState='preview ready';sSaved(sh('sPeopleLifecycle'));return true}if(k==='s-import-commit'){if(x.importState!=='preview ready'||!sCheck('import-review')){sError();return true}x.created=['SIM-ROW-1','SIM-ROW-2'];x.importState='complete';sSaved(q('2 created / 2 skipped with reasons','أُنشئ ٢ وتُرك ٢ بالأسباب'));return true}if(k==='s-import-reconcile'){sSaved(q('Original row receipts unchanged','إيصالات الصفوف الأصلية دون تغيير'));return true}if(k==='s-player-archive'||k==='s-player-restore'){if(!sCheck('archive-review')||!sValue('archive-reason')){sError();return true}x.archived=k.endsWith('archive');sSaved(q('History retained; no deletion','التاريخ محفوظ؛ لا حذف'));return true}if(k==='s-offline-review'||k==='s-offline-mixed'){x.offline='review';sSaved(q('Design fixture only; no offline replay','مثال تصميم فقط؛ لا إعادة إرسال غير متصلة'));return true}return false}
Object.assign(studioRoutes,{sPeopleLifecycle:peopleLifecyclePage,sOffline:offlinePage,sRelease:releasePage});
